window.KS4SRC["efficiency"] = {"common_mistake": "Efficiency = useful output \u00f7 TOTAL INPUT \u2014 not useful \u00f7 wasted. Result must be \u2264 1 (\u2264 100%). If your answer exceeds 1, you have divided the wrong way. Wasted energy = total input \u2212 useful output (not the denominator).", "equations": ["efficiency = useful output energy \u00f7 total input energy", "efficiency = useful power output \u00f7 total power input", "efficiency (%) = (useful output \u00f7 total input) \u00d7 100"], "fifas": [{"label": "Efficiency Calculation", "question": "A car engine uses 20,000 J of chemical energy and produces 7,000 J of useful kinetic energy. Calculate its efficiency.", "steps": [["F", "efficiency = useful output energy \u00f7 total input energy"], ["I", "efficiency = 7000 \u00f7 20,000"], ["F", "efficiency = 0.35"], ["A", "efficiency = 0.35 (35%)"]]}], "higher": "Describe and evaluate specific methods to increase the efficiency of a given energy transfer \u2014 e.g. lubrication reduces friction losses, streamlining reduces air resistance, thermal insulation reduces heat loss, LED technology reduces thermal waste in lighting, regenerative braking recovers kinetic energy. Evaluate cost-effectiveness and practicality of each improvement.", "key_note": "Efficiency = useful output \u00f7 total input (decimal, 0\u20131) or \u00d7 100 for %. Wasted = total \u2212 useful. Sankey diagrams: arrow width \u221d energy amount. Improve: reduce friction (lube), reduce air resistance (streamline), reduce heat loss (insulation), use LEDs. Max efficiency = 100% (never exceeded).", "matching": {"instruction": "Match each device to its efficiency.", "pairs": [["0.75 (75%)", "Motor: 300 J input, 225 J useful mechanical output \u2014 225\u00f7300"], ["0.10 (10%)", "Incandescent bulb: 100 J electrical, 10 J light \u2014 10\u00f7100"], ["0.40 (40%)", "Engine: 500 J chemical, 200 J kinetic \u2014 200\u00f7500"], ["0.90 (90%)", "LED lamp: 100 J electrical, 90 J light \u2014 90\u00f7100"]], "title": "Efficiency Values"}, "quiz": {"CF": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}], "CH": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}], "TF": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}], "TH": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}]}, "summary": "Calculate efficiency as a decimal or percentage and interpret Sankey diagrams.", "theory": [{"content": "EFFICIENCY measures what fraction of total input energy becomes USEFUL output.\n\nNo device is 100% efficient \u2014 some energy is always dissipated as thermal energy or sound.\n\nEQUATIONS:\nefficiency = useful output energy \u00f7 total input energy\nefficiency = useful power output \u00f7 total power input\n\nExpress as:\nDECIMAL: 0 to 1 (e.g. 0.75)\nPERCENTAGE: multiply decimal by 100 (e.g. 75%)\n\nMax efficiency = 1 (100%) \u2014 impossible in practice.\n\nEXAMPLE:\nMotor: 200 J electrical input, 150 J useful mechanical output, 50 J wasted as heat.\nEfficiency = 150 \u00f7 200 = 0.75 = 75%\nWasted = 200 \u2212 150 = 50 J", "heading": "Efficiency \u2014 Definition and Equations"}, {"content": "A SANKEY DIAGRAM shows energy transfers visually:\nArrow WIDTH is proportional to the amount of energy.\nInput arrow on the left. Useful output arrow goes right. Wasted outputs go downward.\n\nReading a Sankey diagram:\nEfficiency = width of useful output \u00f7 width of input arrow.\nThe input arrow = sum of ALL output arrows.\n\nEXAMPLE \u2014 incandescent bulb (very inefficient):\nInput: 100 J electrical\nUseful light output: 10 J (thin right arrow)\nWasted heat: 90 J (wide downward arrow)\nEfficiency = 10 \u00f7 100 = 0.10 = 10%\n\nEXAMPLE \u2014 LED bulb (efficient):\nInput: 100 J\nUseful light: 90 J\nWasted heat: 10 J\nEfficiency = 90 \u00f7 100 = 0.90 = 90%", "heading": "Sankey Diagrams"}, {"content": "REDUCE FRICTION: lubricate moving parts \u2192 less thermal wasted.\nREDUCE AIR RESISTANCE: streamlined shapes \u2192 less energy to air.\nBETTER INSULATION: less thermal energy escapes hot devices.\nBETTER COMPONENTS: LED lights instead of filament bulbs \u2192 more light, less heat.\nREGENERATIVE BRAKING: hybrid/electric cars capture braking KE \u2192 stored in battery rather than wasted as thermal.\n\nWHY EFFICIENCY MATTERS:\nHigher efficiency \u2192 less fuel for same useful output \u2192 lower costs.\nLess fuel \u2192 less CO\u2082 \u2192 lower environmental impact.\nBut: no device can exceed 100% efficiency.", "heading": "Improving Efficiency"}]};
window.KS4SRC["atmospheric-pollutants"] = {"common_mistake": "CO (carbon monoxide) is produced by INCOMPLETE combustion. CO\u2082 is produced by COMPLETE combustion. Both are colourless gases \u2014 but CO is toxic (binds to haemoglobin) while CO\u2082 is not directly toxic at normal concentrations. Catalytic converters reduce CO and NO\u2093 but actually INCREASE CO\u2082 (by converting CO to CO\u2082).", "equations": ["S + O\u2082 \u2192 SO\u2082  (sulfur impurity burning)", "N\u2082 + O\u2082 \u2192 2NO  (in engines at high temperature)", "2CO + 2NO \u2192 2CO\u2082 + N\u2082  (catalytic converter reaction)", "CaCO\u2083 + H\u2082SO\u2084 \u2192 CaSO\u2084 + H\u2082O + CO\u2082  (acid rain dissolving limestone)"], "higher": "Evaluate effectiveness and limitations of pollution control: catalytic converters (reduce CO, NO\u2093 but increase CO\u2082), particulate filters, low-sulfur fuels, electric vehicles (shift emissions to power stations). Evaluate life cycle perspective on different solutions.", "key_note": "Pollutants from fuel combustion: CO (toxic, incomplete combustion), SO\u2082 (acid rain, from sulfur in fuel), NO\u2093 (acid rain, smog, from N\u2082 + O\u2082 at high temperature), particulates (respiratory harm). Acid rain: damages limestone, kills aquatic life. Catalytic converters: convert CO + NO\u2093 \u2192 CO\u2082 + N\u2082.", "matching": {"instruction": "Match each pollutant to its source and main effect.", "pairs": [["Carbon monoxide (CO)", "Incomplete combustion \u2014 toxic gas that prevents oxygen transport in blood"], ["Sulfur dioxide (SO\u2082)", "Sulfur impurities in fuel burned \u2014 causes acid rain damaging buildings and ecosystems"], ["Nitrogen oxides (NO\u2093)", "N\u2082 + O\u2082 at high engine temperatures \u2014 causes acid rain and smog"], ["Particulates (soot)", "Incomplete combustion \u2014 fine particles damage lungs and cause respiratory disease"]], "title": "Pollutant \u2014 Source and Effect"}, "quiz": {"CF": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}], "CH": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}], "TF": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}], "TH": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}]}, "summary": "Describe the pollutants produced by burning fuels and their effects on health and environment.", "theory": [{"content": "Burning FOSSIL FUELS releases several POLLUTANTS in addition to CO\u2082 and water:\n\nCARBON MONOXIDE (CO):\nFrom INCOMPLETE COMBUSTION \u2014 insufficient oxygen.\nCOLOURLESS, ODOURLESS, TOXIC gas.\nBinds to haemoglobin in red blood cells \u2014 prevents oxygen transport \u2192 can be fatal.\nMeasured by CO detectors in homes.\n\nSULFUR DIOXIDE (SO\u2082):\nFuels contain sulfur impurities \u2192 S + O\u2082 \u2192 SO\u2082 when burned.\nCauses ACID RAIN when SO\u2082 reacts with water and oxygen in the atmosphere:\nSO\u2082 + H\u2082O \u2192 H\u2082SO\u2083 (sulfurous acid) / SO\u2083 + H\u2082O \u2192 H\u2082SO\u2084 (sulfuric acid)\nACID RAIN effects: damages buildings/statues (limestone dissolves), kills trees, acidifies lakes killing fish.\nAlso causes respiratory problems \u2014 irritates airways.\n\nNITROGEN OXIDES (NO\u2093 \u2014 mainly NO and NO\u2082):\nProduced when N\u2082 and O\u2082 from air react at the high temperatures inside engines:\nN\u2082 + O\u2082 \u2192 2NO \u2192 oxidised to NO\u2082\nNO\u2093 also causes ACID RAIN (nitric acid).\nContributes to SMOG and LOW-LEVEL OZONE (O\u2083) which irritates lungs.\n\nPARTICULATES (soot/carbon particles):\nFrom incomplete combustion of fuels.\nVery small particles that penetrate deep into lungs.\nCause respiratory disease, aggravate asthma.\nConsciously contribute to GLOBAL DIMMING \u2014 reducing sunlight reaching Earth.", "heading": "Pollutants from Combustion of Fuels"}, {"content": "ACID RAIN forms when sulfur dioxide (SO\u2082) and nitrogen oxides (NO\u2093) dissolve in rainwater:\n\nFORMATION:\nSO\u2082 + H\u2082O + \u00bdO\u2082 \u2192 H\u2082SO\u2084 (sulfuric acid)\n4NO\u2082 + O\u2082 + 2H\u2082O \u2192 4HNO\u2083 (nitric acid)\n\nNormal rain is slightly acidic (pH ~5.6) due to dissolved CO\u2082.\nAcid rain: pH typically 4\u20135 \u2014 10\u00d7 to 100\u00d7 more acidic than normal rain.\n\nEFFECTS:\nBUILDINGS AND STATUES: dissolves limestone and marble:\nCaCO\u2083 + H\u2082SO\u2084 \u2192 CaSO\u2084 + H\u2082O + CO\u2082\nIrreplaceable historical buildings damaged.\n\nECOSYSTEMS:\nLakes and rivers become too acidic for aquatic life \u2014 fish die.\nSoil acidification \u2192 releases toxic aluminium ions \u2192 kills trees.\nForest die-back in areas downwind of industrial zones.\n\nHUMAN HEALTH:\nSO\u2082 and NO\u2082 irritate respiratory system \u2014 worsen asthma, bronchitis.\n\nSOLUTIONS:\nREMOVE SULFUR from fuels before burning (desulfurisation).\nCATALYTIC CONVERTERS in cars \u2014 convert CO, NO\u2093 and unburned hydrocarbons to CO\u2082, N\u2082 and H\u2082O.\nSCRUBBERS in power station chimneys \u2014 spray calcium hydroxide to neutralise SO\u2082.", "heading": "Acid Rain \u2014 Causes and Effects"}, {"content": "CATALYTIC CONVERTERS convert toxic exhaust gases to less harmful ones:\n\nPLATINUM AND RHODIUM catalysts:\n2CO + 2NO \u2192 2CO\u2082 + N\u2082\n(toxic carbon monoxide + toxic nitrogen oxide \u2192 CO\u2082 + harmless nitrogen)\n\nAlso convert unburned hydrocarbons:\nHydrocarbon + O\u2082 \u2192 CO\u2082 + H\u2082O\n\nReduces: CO (toxic), NO\u2093 (acid rain, smog) and particulates.\nDoes NOT reduce CO\u2082 (a greenhouse gas) \u2014 actually increases CO\u2082 by converting CO to CO\u2082.\n\nOTHER SOLUTIONS:\nLOW-SULFUR FUELS \u2014 reduce SO\u2082 at source.\nPARTICULATE FILTERS in diesel vehicles.\nELECTRIC VEHICLES \u2014 no exhaust combustion pollutants (though power station emissions are a separate issue).\nIMPROVED ENGINE DESIGN \u2014 more complete combustion, less CO and particulates.\nINTERNATIONAL AGREEMENTS \u2014 e.g. limits on SO\u2082 emissions from power stations.", "heading": "Catalytic Converters and Reducing Pollution"}]};
window.KS4SRC["infrared-black-bodies"] = {"common_mistake": "A PERFECT BLACK BODY is black because it absorbs ALL radiation \u2014 it also emits MAXIMUM radiation for its temperature. Being a 'perfect emitter' and 'perfect absorber' go together. Hotter objects emit at SHORTER wavelengths \u2014 this seems counterintuitive but is why glowing objects change colour from red to white-hot as they get hotter.", "higher": "Explain black body radiation curves \u2014 how peak wavelength depends on temperature. Describe how Earth's radiation balance determines its temperature. Explain the greenhouse effect mechanistically. Evaluate how changes in albedo or greenhouse gas concentration affect Earth's temperature.", "key_note": "All objects emit and absorb IR. Dark matt = best emitter and absorber. Shiny = best reflector. Black body: absorbs all radiation, emits maximum for its temperature. Hotter \u2192 more emission at shorter wavelength. Stars: colour indicates temperature (red=cool, blue=hot). Earth absorbs solar, re-emits IR \u2014 greenhouse effect.", "matching": {"instruction": "Match each statement to the correct concept.", "pairs": [["Dark matt surface", "Best emitter and absorber of infrared radiation"], ["Perfect black body", "Absorbs all incident radiation \u2014 emits maximum radiation for its temperature"], ["Hotter object", "Emits more radiation AND at shorter wavelengths \u2014 peak shifts towards visible/UV"], ["Blue-white star", "Very hot (~30,000 K) \u2014 peak emission in UV/blue visible range"]], "title": "Infrared and Black Bodies"}, "quiz": {"TF": [{"opts": [["As temperature increases, the peak emission shifts to shorter wavelengths \u2014 from infrared through red to shorter visible wavelengths approaching white", true], ["The metal changes chemical composition as it gets hotter, producing different coloured oxides", false], ["Different wavelengths of light are produced by different electrons in the metal", false], ["White light contains all colours \u2014 the metal must be emitting all wavelengths at low temperature but only red at high temperature", false]], "q": "A metal rod is heated in a furnace. First it glows red, then orange, then white. What does this tell us?", "wrong_explanations": {"1": "The colour change is due to temperature-dependent emission spectra \u2014 not chemical changes. A pure metal rod would show the same progression.", "2": "Different electrons in the metal contribute to emission, but the pattern follows the temperature-dependent black body spectrum \u2014 the overall colour shift is about temperature.", "3": "White hot means the peak has moved to visible wavelengths with broad-spectrum emission \u2014 cool objects emit IR (invisible) then progress through red, orange, yellow to white as temperature rises."}}, {"opts": [["Silvered walls are poor emitters and poor absorbers of infrared \u2014 they reflect radiation back, reducing thermal energy transfer by radiation", true], ["Silver is a good conductor \u2014 it rapidly distributes heat evenly around the flask walls", false], ["Silver reacts with oxygen in the air \u2014 the oxide layer acts as an insulator", false], ["The bright colour of silver reflects external light, keeping the flask cool", false]], "q": "Why are the walls of a thermos flask silvered?", "wrong_explanations": {"1": "Silver is an excellent conductor \u2014 but the silvered wall is there to REDUCE radiation transfer, not to conduct heat.", "2": "Silver doesn't form a significant protective oxide layer at room temperature \u2014 the silvering works by reflection of radiation.", "3": "Visible light reflection is not the primary reason \u2014 it's the IR radiation reflection that reduces thermal energy transfer."}}], "TH": [{"opts": [["As temperature increases, the peak emission shifts to shorter wavelengths \u2014 from infrared through red to shorter visible wavelengths approaching white", true], ["The metal changes chemical composition as it gets hotter, producing different coloured oxides", false], ["Different wavelengths of light are produced by different electrons in the metal", false], ["White light contains all colours \u2014 the metal must be emitting all wavelengths at low temperature but only red at high temperature", false]], "q": "A metal rod is heated in a furnace. First it glows red, then orange, then white. What does this tell us?", "wrong_explanations": {"1": "The colour change is due to temperature-dependent emission spectra \u2014 not chemical changes. A pure metal rod would show the same progression.", "2": "Different electrons in the metal contribute to emission, but the pattern follows the temperature-dependent black body spectrum \u2014 the overall colour shift is about temperature.", "3": "White hot means the peak has moved to visible wavelengths with broad-spectrum emission \u2014 cool objects emit IR (invisible) then progress through red, orange, yellow to white as temperature rises."}}, {"opts": [["Silvered walls are poor emitters and poor absorbers of infrared \u2014 they reflect radiation back, reducing thermal energy transfer by radiation", true], ["Silver is a good conductor \u2014 it rapidly distributes heat evenly around the flask walls", false], ["Silver reacts with oxygen in the air \u2014 the oxide layer acts as an insulator", false], ["The bright colour of silver reflects external light, keeping the flask cool", false]], "q": "Why are the walls of a thermos flask silvered?", "wrong_explanations": {"1": "Silver is an excellent conductor \u2014 but the silvered wall is there to REDUCE radiation transfer, not to conduct heat.", "2": "Silver doesn't form a significant protective oxide layer at room temperature \u2014 the silvering works by reflection of radiation.", "3": "Visible light reflection is not the primary reason \u2014 it's the IR radiation reflection that reduces thermal energy transfer."}}]}, "summary": "Describe infrared emission and absorption by surfaces and explain perfect black body radiation.", "theory": [{"content": "All objects emit and absorb THERMAL RADIATION (infrared radiation) continuously.\n\nEMISSION:\nAll objects above absolute zero emit infrared radiation.\nHotter objects emit MORE radiation and at SHORTER wavelengths (higher frequency, more energetic).\n\nABSORPTION:\nObjects absorb radiation from their surroundings.\nDark, matt surfaces are better ABSORBERS than light, shiny surfaces.\n\nDark matt surfaces are also better EMITTERS.\nShiny, light surfaces are better REFLECTORS and poorer emitters/absorbers.\n\nEMISSION vs ABSORPTION RATES:\nIf emission rate > absorption rate \u2192 object cools.\nIf absorption rate > emission rate \u2192 object heats up.\nIf rates are equal \u2192 temperature is constant (thermal equilibrium).", "heading": "Emission and Absorption of Radiation"}, {"content": "A PERFECT BLACK BODY is a theoretical object that:\nABSORBS all radiation that falls on it (reflects none).\nEMITS the maximum amount of radiation for its temperature.\n\nPerfect black bodies emit the most radiation of any object at the same temperature.\nThe emission spectrum of a black body depends ONLY on temperature \u2014 not on the material.\n\nBLACK BODY RADIATION CURVES:\nAs temperature increases:\nPeak of emission shifts to SHORTER wavelengths (higher frequency).\nTotal energy emitted per second INCREASES dramatically.\n\nEXAMPLE:\nA cool object: emits mainly low-frequency infrared \u2014 invisible to the eye.\nHot iron (600\u00b0C): glows dull red \u2014 emitting visible red light.\nVery hot iron (1000\u00b0C): orange-white \u2014 peak moves into visible range.\nThe Sun (~5500\u00b0C surface): peak emission in visible light (yellow-green).\n\nA cavity with a small hole acts as an approximate black body.", "heading": "Perfect Black Bodies"}, {"content": "STARS AS BLACK BODIES:\nStars approximately behave as black bodies.\nThe colour of a star indicates its surface temperature:\nRed stars (~3000 K) \u2192 cool \u2192 peak in infrared/red.\nYellow stars (like the Sun, ~5500 K) \u2192 medium \u2192 peak in visible.\nBlue-white stars (~30,000 K) \u2192 very hot \u2192 peak in UV/blue.\n\nEARTH'S TEMPERATURE:\nThe Earth absorbs solar radiation and re-emits as infrared (longer wavelength \u2014 Earth is cooler than Sun).\nGreenhouse gases absorb Earth's infrared emission \u2192 trap energy \u2192 warming effect.\n\nTHERMAL CAMERAS:\nDetect infrared emitted by warm objects \u2014 used in: night vision, firefighting, medical diagnosis (detecting hot spots), building inspection (heat loss).\n\nSPACE TELESCOPES:\nInfrared telescopes detect emission from cool objects like dust clouds in space.\nHubble detects visible light; James Webb Space Telescope detects infrared.\n\nSELECTIVE EMISSION AND ABSORPTION:\nSolar panels: dark, matt surfaces to maximise solar absorption.\nSolar water heaters: black tubes to maximise absorption.\nThermos flasks: silvered walls to minimise emission and absorption (reflect radiation back).", "heading": "Applications"}]};
window.KS4SRC["periodic-table"] = {"common_mistake": "The GROUP NUMBER tells you the number of OUTER ELECTRONS \u2014 not the total electrons or the period. The PERIOD NUMBER tells you how many shells. So an element in Period 3, Group 2 has 3 shells and 2 outer electrons \u2014 electronic configuration 2.8.2 (magnesium). Don't confuse groups and periods.", "higher": "Detailed group trends explained by electronic structure. Group 1 reactivity increases down (outer electron further from nucleus, weaker attraction, lower ionisation energy). Group 7 reactivity decreases down (outer shell further, weaker pull on incoming electron). Predict properties of unknown elements from position.", "key_note": "Periodic table arranged by atomic number. Period = row = number of shells. Group = column = number of outer electrons. Same group = same outer electrons = similar properties. Metals: left and centre. Non-metals: top right. Noble gases: Group 0 (right edge).", "matching": {"instruction": "Match each feature to its correct description.", "pairs": [["Period", "A horizontal row \u2014 each new period means another electron shell"], ["Group", "A vertical column \u2014 elements share the same number of outer electrons"], ["Group 0", "Noble gases \u2014 full outer shells, very unreactive"], ["Transition metals", "Hard, dense metals with high melting points \u2014 form coloured compounds, act as catalysts"], ["Group 1", "Alkali metals \u2014 1 outer electron, very reactive, soft, low density"]], "title": "Match the Periodic Table Feature"}, "quiz": {"CF": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}], "CH": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}], "TF": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}], "TH": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}]}, "summary": "Describe the structure of the periodic table and explain how it is organised.", "theory": [{"content": "The PERIODIC TABLE arranges all known elements in order of increasing ATOMIC NUMBER.\n\nKey features:\nROWS are called PERIODS \u2014 each period represents a new electron shell being filled.\nCOLUMNS are called GROUPS \u2014 elements in the same group have the same number of OUTER ELECTRONS and similar chemical properties.\n\nPeriod numbers tell you how many electron shells the element has:\nPeriod 1: 1 shell (H and He)\nPeriod 2: 2 shells (Li to Ne)\nPeriod 3: 3 shells (Na to Ar)\n\nGroup numbers (1\u20137 and 0) tell you how many OUTER electrons:\nGroup 1: 1 outer electron\nGroup 7: 7 outer electrons\nGroup 0: full outer shell (8 electrons, or 2 for helium)\n\nThe periodic table is divided into:\nMETALS \u2014 left and centre (most elements are metals).\nNON-METALS \u2014 top right.\nMETALLOIDS/SEMI-METALS \u2014 along the dividing line (e.g. silicon, germanium).", "heading": "Structure of the Periodic Table"}, {"content": "ACROSS A PERIOD (left to right):\nAtomic number increases.\nNumber of electrons in outer shell increases (1 to 8).\nMetallic properties decrease \u2014 non-metallic properties increase.\nFrom metal (Group 1) to non-metal (Group 7) to noble gas (Group 0).\n\nDOWN A GROUP:\nAnother electron shell is added.\nAtoms get LARGER (more shells = bigger atom).\nOUTER ELECTRONS are further from the nucleus \u2014 less strongly attracted.\nMETALS become MORE REACTIVE going down (easier to lose outer electron).\nNON-METALS become LESS REACTIVE going down (harder to gain another electron \u2014 outer electrons are further away).\n\nThese trends allow chemists to PREDICT the properties of elements from their position in the periodic table.", "heading": "Trends Across Periods and Down Groups"}, {"content": "Between Groups 2 and 3 lies the TRANSITION METALS block (the long middle section).\n\nTransition metals are harder and have higher melting points than Group 1 metals.\nThey are typically dense, strong, shiny metals.\nExamples: iron (Fe), copper (Cu), zinc (Zn), titanium (Ti), nickel (Ni), gold (Au), silver (Ag).\n\nKey properties of transition metals:\nForm COLOURED COMPOUNDS \u2014 e.g. copper sulfate is blue; iron(II) compounds are pale green; iron(III) compounds are orange.\nCan act as CATALYSTS \u2014 e.g. iron catalyst in the Haber process; nickel in hydrogenation.\nCan have MULTIPLE OXIDATION STATES \u2014 e.g. iron can be Fe\u00b2\u207a or Fe\u00b3\u207a.\n\nCompare with Group 1 metals: transition metals are less reactive, harder, have higher melting points and form coloured compounds. Group 1 metals are soft, very reactive and their compounds are usually white.", "heading": "Transition Metals"}]};
window.KS4SRC["thermal-conductivity"] = {"common_mistake": "INSULATORS do not stop heat transfer \u2014 they slow it down. A perfect insulator doesn't exist. Trapped air is one of the best insulators because air is a poor conductor and convection is reduced when it is trapped in small spaces.", "higher": "Describe the factors affecting the rate of thermal conduction: thermal conductivity, thickness and temperature difference. Calculate rate of energy transfer through a material. Evaluate different insulation methods quantitatively using U-values or thermal conductivity data. Explain why double-glazing is more effective with wider gaps.", "key_note": "Thermal conductivity: rate of energy transfer by conduction. Metals = good conductors (free electrons). Air/fibreglass = good insulators. Reducing losses: insulation, lubrication, streamlining. Thicker insulation = less energy lost. RP2: compare materials by rate of cooling.", "matching": {"instruction": "Match each material to its thermal conductivity property.", "pairs": [["Copper", "Very high thermal conductivity \u2014 free electrons transfer energy rapidly"], ["Air (trapped)", "Very low thermal conductivity \u2014 excellent insulator when trapped"], ["Cavity wall insulation", "Fibreglass with trapped air \u2014 reduces energy loss through walls"], ["Lubrication", "Reduces friction between surfaces \u2014 less energy wasted as heat"]], "title": "Thermal Conductivity"}, "quiz": {"CF": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}], "CH": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}], "TF": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}], "TH": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}]}, "rp": "RP2 (physics only) \u2014 Investigate effectiveness of different thermal insulators. Measure rate of cooling of hot water wrapped in different materials.", "summary": "Explain thermal conductivity and describe how insulation reduces unwanted energy transfers.", "theory": [{"content": "THERMAL CONDUCTIVITY measures how well a material transfers thermal energy by conduction.\n\nGood THERMAL CONDUCTORS: metals (copper, aluminium, iron). Transfer energy quickly. Free electrons carry thermal energy through the material.\n\nGood THERMAL INSULATORS: air, wood, fibreglass, polystyrene, wool. Transfer energy slowly. No free electrons; energy transferred only by vibration between tightly packed or sparse particles.\n\nUnit of thermal conductivity: W/m\u00b7K (watts per metre per kelvin).\n\nHigher thermal conductivity \u2192 energy transferred faster for the same temperature difference and thickness.\n\nExamples:\nCopper: ~400 W/m\u00b7K \u2014 excellent conductor.\nGlass: ~1 W/m\u00b7K \u2014 poor conductor.\nAir: ~0.025 W/m\u00b7K \u2014 excellent insulator.", "heading": "Thermal Conductivity"}, {"content": "All energy transfers involve some unwanted dissipation \u2014 energy transferred to the thermal store of the surroundings.\n\nMETHODS TO REDUCE THERMAL ENERGY LOSS:\n\n1. INSULATION:\nSurround objects with poor conductors.\nCavity wall insulation (fibreglass or foam) \u2014 reduces conduction through walls.\nLoft insulation \u2014 reduces conduction through roof.\nDouble-glazing \u2014 air gap between panes of glass reduces conduction.\nFoam lagging on hot water pipes \u2014 reduces heat loss to surroundings.\n\n2. LUBRICATION:\nReduces friction between moving surfaces.\nLess friction \u2192 less thermal energy dissipated.\nMachine oil, grease used in engines, bearings, chains.\n\n3. STREAMLINING:\nReduces air resistance on moving vehicles.\nLess drag \u2192 less energy wasted overcoming resistance.\n\n4. ELECTROMAGNETIC SHIELDING:\nReduces energy loss from electrical components.\n\nTHICKNESS AND THERMAL CONDUCTIVITY:\nThicker insulation \u2192 less energy transferred per second (for same temperature difference).\nMore insulating material (lower conductivity) \u2192 less energy transferred.\nEnergy lost per second \u221d thermal conductivity \u00d7 area \u00d7 (temperature difference) \u00f7 thickness.", "heading": "Reducing Unwanted Energy Transfers"}, {"content": "REQUIRED PRACTICAL (RP2 \u2014 physics only):\nInvestigate the effectiveness of different materials as thermal insulators.\n\nMETHOD:\nWrap beakers of hot water in different materials (wool, bubble wrap, newspaper, foil).\nMeasure temperature of water at regular time intervals.\nPlot temperature-time graphs for each material.\nCompare rate of cooling \u2014 steeper gradient = less effective insulator.\n\nVARIABLES:\nIndependent: type of insulating material.\nDependent: rate of cooling (temperature change per unit time).\nControlled: initial temperature, volume of water, thickness of insulation, surface area.\n\nCONCLUSION:\nMaterial with lowest thermal conductivity \u2192 slowest cooling \u2192 best insulator.\nAir is often the best insulator \u2014 sealed air pockets in fibreglass work well.\n\nAPPLICATIONS:\nBuilding insulation \u2014 reduces heating bills and carbon footprint.\nRefrigeration \u2014 insulated walls slow thermal energy entering the cold space.\nCryogenics \u2014 extreme insulation to maintain very low temperatures.", "heading": "Required Practical \u2014 Thermal Insulation"}]};
window.KS4SRC["development-periodic-table"] = {"common_mistake": "Mendeleev arranged elements by RELATIVE ATOMIC MASS \u2014 the MODERN table is arranged by ATOMIC NUMBER. Mendeleev's arrangement had a few inconsistencies because Ar and atomic number don't always match perfectly (e.g. argon and potassium). The modern arrangement by atomic number resolves all these problems.", "key_note": "Newlands: octaves \u2014 every 8th element similar \u2014 rejected (didn't work for all elements, no gaps). Mendeleev: arranged by Ar, left gaps, predicted missing elements \u2014 accepted when predictions proved correct. Modern table: arranged by atomic number (Moseley, 1913).", "matching": {"instruction": "Match each scientist to their contribution to the periodic table.", "pairs": [["Newlands", "Law of Octaves \u2014 every 8th element similar \u2014 not accepted by scientists at the time"], ["Mendeleev", "Left gaps for undiscovered elements, predicted their properties \u2014 table accepted when predictions proved correct"], ["Moseley", "Arranged elements by atomic number (protons) \u2014 resolved inconsistencies in Mendeleev's Ar-based table"]], "title": "Match the Scientist to their Contribution"}, "quiz": {"CF": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}], "CH": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}], "TF": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}], "TH": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}]}, "summary": "Describe how the periodic table developed, including Newlands and Mendeleev's contributions.", "theory": [{"content": "Before atomic numbers were understood, scientists tried to classify elements based on RELATIVE ATOMIC MASS.\n\nJOHN NEWLANDS \u2014 Law of Octaves (1864):\nArranged elements by increasing Ar.\nNoticed that every 8th element had similar properties \u2014 called it the 'Law of Octaves' (like musical notes).\nLimitations:\nOnly worked for the first 16 elements.\nForced elements into groups even when properties didn't match.\nLeft no gaps for undiscovered elements.\nThe scientific community did not accept his work.\n\nDMITRI MENDELEEV \u2014 first successful periodic table (1869):\nAlso arranged elements by increasing Ar.\nKey improvements over Newlands:\nLeft GAPS for undiscovered elements \u2014 predicted their properties.\nRearranged some elements to make groups match better (putting chemical properties above strict Ar order).\nPredicted EKA-SILICON (now known as germanium) \u2014 when it was discovered in 1886, its properties closely matched Mendeleev's prediction.\nThis predictive power convinced the scientific community to accept the table.", "heading": "Early Attempts at Classification"}, {"content": "The modern periodic table was only possible after the discovery of subatomic particles.\n\nHENRY MOSELEY (1913):\nUsed X-ray experiments to determine ATOMIC NUMBERS of elements.\nRealised elements should be arranged by ATOMIC NUMBER (protons), not atomic mass.\nThis resolved several inconsistencies in Mendeleev's table where some elements seemed in the wrong order when arranged by Ar.\n\nKey improvement: arranging by atomic number places elements in the correct groups without exception \u2014 it is the atomic number (protons = electrons) that determines chemical properties, not mass.\n\nDISCOVERY OF NOBLE GASES:\nArgon (1894) and other noble gases were discovered AFTER Mendeleev's table \u2014 but they fit perfectly as a new Group 0.\nThis was further evidence for the validity of the periodic table structure.", "heading": "The Modern Periodic Table"}, {"content": "Mendeleev's table was eventually accepted by the scientific community for three main reasons:\n\n1. PREDICTIVE POWER: He predicted properties of undiscovered elements (eka-aluminium = gallium, eka-silicon = germanium, eka-boron = scandium). When discovered, they matched his predictions closely.\n\n2. GAPS: Leaving gaps was a bold scientific decision \u2014 it showed the table was a genuine model of underlying patterns, not just a classification of known elements.\n\n3. EXPLAINING PATTERNS: The table explained why elements in the same group reacted similarly \u2014 it made chemistry more systematic and predictable.\n\nScience accepts models when they successfully PREDICT new observations \u2014 Mendeleev's table did exactly this.", "heading": "Why Mendeleev's Table was Accepted"}]};
window.KS4SRC["uses-em-waves"] = {"common_mistake": "MRI scanners use RADIO WAVES (not X-rays) \u2014 they are safe for soft tissue imaging with no ionising radiation. X-rays are used for imaging BONE and dense structures. Also: microwaves for SATELLITE communication (pass through ionosphere); radio waves for BROADCAST (reflect off ionosphere).", "higher": "Explain why different wavelengths of EM radiation are used for different applications in terms of their properties \u2014 penetration, absorption, reflection and refraction behaviour. Evaluate the hazards and benefits of each type in context (e.g. X-rays vs MRI vs ultrasound for medical imaging). Explain how optical fibres work using total internal reflection.", "key_note": "Radio: broadcast, MRI. Microwave: satellites, phones, radar, cooking. IR: heating, remote controls, night vision, fibre optics. Visible: photography, fibre optics, photosynthesis. UV: sterilisation, fluorescence, vitamin D. X-ray: medical imaging, airport security, CT. Gamma: radiotherapy, sterilisation, tracers.", "matching": {"instruction": "Match each application to the EM wave type used.", "pairs": [["Radio waves", "MRI scanner \u2014 safe for soft tissue, no ionising radiation"], ["Microwaves", "Satellite communication \u2014 passes through ionosphere to reach satellites"], ["Infrared", "TV remote control \u2014 pulses of IR carry the signal to the TV"], ["X-rays", "Medical imaging of bones \u2014 absorbed by dense bone, transmitted by soft tissue"], ["Gamma rays", "Radiotherapy \u2014 focused beams kill cancer cells"]], "title": "EM Wave Applications"}, "quiz": {"CF": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}], "CH": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}], "TF": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}], "TH": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}]}, "summary": "Describe the uses of each type of electromagnetic wave and explain why each type is suitable.", "theory": [{"content": "RADIO WAVES:\nBROADCASTING: AM and FM radio, TV broadcasts \u2014 travel long distances, reflect off ionosphere.\nCOMMUNICATION: aircraft, ships, emergency services.\nASTRONOMY: radio telescopes detect radio waves from distant stars and galaxies.\nMRI SCANNERS: radio waves + magnetic field \u2192 detailed images of soft tissue (no ionising radiation).\n\nMICROWAVES:\nMOBILE PHONES AND WIFI: short-range communication.\nSATELLITE COMMUNICATION: microwaves pass through the atmosphere and ionosphere (radio waves reflect off ionosphere \u2014 limited for satellite use).\nMICROWAVE OVENS: microwave frequency matches water molecules' resonance \u2192 absorbed \u2192 food heats from inside.\nRADAR: detect aircraft, ships, weather systems \u2014 measure distance by timing reflection.", "heading": "Uses of Radio Waves and Microwaves"}, {"content": "INFRARED (IR):\nHEATING: electric heaters, grills \u2014 absorbed by surfaces, converted to heat.\nREMOTE CONTROLS: TV, DVD players \u2014 IR pulses carry coded signals.\nFIBRE OPTICS: IR carried along optical fibres for high-speed internet.\nNIGHT VISION CAMERAS: detect IR emitted by warm bodies \u2014 useful in darkness.\nTHERMAL IMAGING: medical, security, wildlife observation.\n\nVISIBLE LIGHT:\nPHOTOGRAPHY: cameras capture visible light.\nFIBRE OPTICS: carries data as light pulses \u2014 basis of broadband internet.\nPHOTOSYNTHESIS: plants absorb red and blue light.\nLASERS: surgery, barcode scanners, DVD reading.\n\nULTRAVIOLET (UV):\nSTERILISATION: UV kills bacteria and viruses \u2014 used in hospitals and water treatment.\nFLUORESCENCE: some materials emit visible light when absorbing UV \u2014 security markings, fluorescent lamps.\nBLACK LIGHTS: detect forged bank notes (UV-reactive ink).\nVITAMIN D PRODUCTION: skin produces vitamin D when exposed to UV.", "heading": "Uses of Infrared, Visible and Ultraviolet"}, {"content": "X-RAYS:\nMEDICAL IMAGING: pass through soft tissue, absorbed by bone \u2192 shadow on film/detector.\nCT SCANS: multiple X-ray beams \u2192 3D image of internal structures.\nAIRPORT SECURITY: luggage scanning \u2014 detect metal, explosives.\nMATERIAL TESTING: checking for cracks in metal castings and welds.\n\nGAMMA RAYS:\nCANCER TREATMENT (radiotherapy): focused beams kill tumour cells.\nST ERILISATION of medical equipment: kills all microorganisms without heat.\nFOOD IRRADIATION: kills bacteria in food \u2192 longer shelf life.\nMEDICAL TRACERS: gamma-emitting radioisotopes injected \u2192 gamma camera detects distribution in body \u2192 reveals organ function.\nTHICKNESS MONITORING: detect gamma penetration through materials in manufacturing.\n\nMATCHING APPLICATION TO WAVE TYPE:\nThe wave chosen matches its properties to the application:\nMust penetrate enough \u2192 not be absorbed too quickly.\nMust interact appropriately with the target material.\nHazard must be managed \u2014 ionising types minimised.", "heading": "Uses of X-rays and Gamma Rays"}]};
